// App State
let currentChapter = 1;
let currentTheme = 'dark';
let currentFontSize = 18;
let currentWidth = 100; // % width of reading area

// Simulated Lord Dashboard state
let lordResources = {
    iron: 820,
    food: 15,
    security: 45,
    population: 1240,
    reincarnationLoop: 1,
    currentAge: 16,
    loopLifespan: 120,
    sectRank: 18,
    soulAura: 0
};

let solvedProblems = [];

// Initialize Page
document.addEventListener("DOMContentLoaded", () => {
    setupNavigation();
    setupReaderSettings();
    renderChapter();
    renderWiki();
    renderDashboard();
    setupDashboardActions();
});

// Sidebar navigation handler
function setupNavigation() {
    const navItems = document.querySelectorAll(".nav-item");
    const views = document.querySelectorAll(".content-view");
    
    navItems.forEach(item => {
        item.addEventListener("click", (e) => {
            e.preventDefault();
            const targetViewId = item.getAttribute("data-target");
            
            navItems.forEach(i => i.classList.remove("active"));
            views.forEach(v => v.classList.remove("active"));
            
            item.classList.add("active");
            document.getElementById(targetViewId).classList.add("active");
            
            if (window.innerWidth <= 992) {
                document.querySelector(".main-content").scrollTop = 0;
            }
        });
    });
}

// Novel Reader Logic
function renderChapter() {
    const chapter = NOVEL_DATA.chapters.find(c => c.id === currentChapter);
    if (!chapter) return;
    
    const readerTitle = document.getElementById("reader-title");
    const readerContent = document.getElementById("reader-content");
    
    readerTitle.innerHTML = `<h2>${chapter.title}</h2>`;
    readerContent.innerHTML = chapter.content;

    // Populate and update chapter selector dropdown
    const select = document.getElementById("chapter-select");
    if (select) {
        if (select.options.length !== NOVEL_DATA.chapters.length) {
            select.innerHTML = "";
            NOVEL_DATA.chapters.forEach(c => {
                const opt = document.createElement("option");
                opt.value = c.id;
                opt.text = c.title.split(":")[0] + ": " + c.title.split(":").slice(1).join(":"); // Keeps it brief
                select.appendChild(opt);
            });
        }
        select.value = currentChapter;
    }
    
    // Update reader stats warning
    const readerStatsText = document.getElementById("reader-stats-text");
    readerStatsText.innerHTML = `
        <span>ประชากร: <strong>${chapter.status.population} คน</strong></span> | 
        <span>ความปลอดภัย: <strong>${chapter.status.security}</strong></span> | 
        <span>แร่เหล็ก: <strong>${chapter.status.iron} หน่วย</strong></span> | 
        <span>เสบียง: <strong>${chapter.status.food} วัน</strong></span>
    `;

    // Sync story stats with Dashboard if it hasn't been modified by user interaction
    if (solvedProblems.length === 0) {
        lordResources.iron = chapter.status.iron;
        lordResources.food = chapter.status.food;
        lordResources.security = parseInt(chapter.status.security);
        lordResources.population = chapter.status.population;
        
        // Dynamically update age and loop based on active chapter
        if (currentChapter <= 2) {
            lordResources.currentAge = 24;
            lordResources.reincarnationLoop = 1;
        } else {
            lordResources.reincarnationLoop = 2;
            if (currentChapter === 3) {
                lordResources.currentAge = 16;
            } else if (currentChapter >= 4 && currentChapter <= 5) {
                lordResources.currentAge = 7;
            } else if (currentChapter >= 6 && currentChapter <= 10) {
                lordResources.currentAge = 8;
            } else if (currentChapter >= 11 && currentChapter <= 15) {
                lordResources.currentAge = 9;
            } else if (currentChapter >= 16 && currentChapter <= 20) {
                lordResources.currentAge = 16;
            } else if (currentChapter === 21) {
                lordResources.currentAge = 17;
            } else if (currentChapter === 22) {
                lordResources.currentAge = 19;
            } else if (currentChapter === 23) {
                lordResources.currentAge = 21;
            } else if (currentChapter === 24) {
                lordResources.currentAge = 23;
            } else if (currentChapter === 25) {
                lordResources.currentAge = 26;
            } else if (currentChapter === 26) {
                lordResources.currentAge = 28;
            } else if (currentChapter === 27) {
                lordResources.currentAge = 29;
            } else if (currentChapter === 28) {
                lordResources.currentAge = 30;
            } else if (currentChapter >= 29 && currentChapter <= 30) {
                lordResources.currentAge = 31;
            } else if (currentChapter >= 31 && currentChapter <= 33) {
                lordResources.currentAge = 32;
            } else if (currentChapter >= 34 && currentChapter <= 36) {
                lordResources.currentAge = 33;
            } else if (currentChapter >= 37) {
                lordResources.currentAge = 34;
            }
        }
        updateDashboardUI();
    }
    
    // Setup chapter navigation buttons
    const prevBtn = document.getElementById("prev-chapter-btn");
    const nextBtn = document.getElementById("next-chapter-btn");
    
    if (currentChapter === 1) {
        prevBtn.style.visibility = "hidden";
    } else {
        prevBtn.style.visibility = "visible";
    }
    
    if (currentChapter === NOVEL_DATA.chapters.length) {
        nextBtn.style.visibility = "hidden";
    } else {
        nextBtn.style.visibility = "visible";
    }
}

function setupReaderSettings() {
    // Collapsible buttons logic
    const toggleSettingsBtn = document.getElementById("toggle-settings-btn");
    const settingsPanel = document.getElementById("reader-settings-panel");
    if (toggleSettingsBtn && settingsPanel) {
        toggleSettingsBtn.addEventListener("click", () => {
            settingsPanel.classList.toggle("collapsed");
            toggleSettingsBtn.classList.toggle("active");
        });
    }

    const toggleStatsBtn = document.getElementById("toggle-stats-btn");
    const statsPanel = document.getElementById("reader-stats-text");
    if (toggleStatsBtn && statsPanel) {
        toggleStatsBtn.addEventListener("click", () => {
            statsPanel.classList.toggle("collapsed");
            toggleStatsBtn.classList.toggle("active");
        });
    }

    // Copy script button for Clipchamp TTS
    const copyTtsBtn = document.getElementById("copy-tts-btn");
    if (copyTtsBtn) {
        copyTtsBtn.addEventListener("click", () => {
            const chapter = NOVEL_DATA.chapters.find(c => c.id === currentChapter);
            if (!chapter) return;
            
            // Clean content for TTS
            let cleanText = chapter.content;
            // 1. Remove details blocks (character profiles)
            cleanText = cleanText.replace(/<details[^>]*>[\s\S]*?<\/details>/gi, '');
            // 2. Remove all HTML tags
            cleanText = cleanText.replace(/<[^>]*>/g, '');
            // 3. Remove metadata in square brackets
            cleanText = cleanText.replace(/\[[^\]]*\]/g, '');
            // 4. Decode HTML entities
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = cleanText;
            cleanText = tempDiv.innerText || tempDiv.textContent || '';
            // 5. Trim and clean spacing
            cleanText = cleanText.split('\n')
                                 .map(line => line.trim())
                                 .filter(line => line.length > 0)
                                 .join('\n\n');

            navigator.clipboard.writeText(cleanText).then(() => {
                copyTtsBtn.innerHTML = '<i class="fa-solid fa-circle-check"></i> คัดลอกบทพากย์สำเร็จ!';
                copyTtsBtn.style.color = "var(--color-secondary)";
                setTimeout(() => {
                    copyTtsBtn.innerHTML = '<i class="fa-solid fa-microphone-lines"></i> คัดลอกบทพากย์เสียง';
                    copyTtsBtn.style.color = "";
                }, 2000);
            }).catch(err => {
                console.error("Failed to copy voiceover script: ", err);
                alert("เกิดข้อผิดพลาดในการคัดลอก กรุณาลองใหม่อีกครั้ง");
            });
        });
    }

    // Chapter buttons
    document.getElementById("prev-chapter-btn").addEventListener("click", (e) => {
        e.preventDefault();
        if (currentChapter > 1) {
            currentChapter--;
            renderChapter();
            document.querySelector(".main-content").scrollTop = 0;
        }
    });
    
    document.getElementById("next-chapter-btn").addEventListener("click", (e) => {
        e.preventDefault();
        if (currentChapter < NOVEL_DATA.chapters.length) {
            currentChapter++;
            renderChapter();
            document.querySelector(".main-content").scrollTop = 0;
        }
    });

    // Chapter select dropdown change listener
    const selectEl = document.getElementById("chapter-select");
    if (selectEl) {
        selectEl.addEventListener("change", (e) => {
            currentChapter = parseInt(e.target.value);
            renderChapter();
            document.querySelector(".main-content").scrollTop = 0;
        });
    }

    // Theme dots
    const dots = document.querySelectorAll(".theme-dot");
    dots.forEach(dot => {
        dot.addEventListener("click", () => {
            dots.forEach(d => d.classList.remove("active"));
            dot.classList.add("active");
            
            const theme = dot.getAttribute("data-theme");
            document.body.className = "";
            if (theme !== 'dark') {
                document.body.classList.add(`mode-${theme}`);
            }
            currentTheme = theme;
        });
    });

    // Font size controls
    const readerBody = document.getElementById("reader-content");
    document.getElementById("font-dec-btn").addEventListener("click", () => {
        if (currentFontSize > 14) {
            currentFontSize -= 2;
            readerBody.style.fontSize = `${currentFontSize}px`;
            document.getElementById("font-size-label").innerText = `${currentFontSize}px`;
        }
    });
    
    document.getElementById("font-inc-btn").addEventListener("click", () => {
        if (currentFontSize < 26) {
            currentFontSize += 2;
            readerBody.style.fontSize = `${currentFontSize}px`;
            document.getElementById("font-size-label").innerText = `${currentFontSize}px`;
        }
    });

    // Width controls
    const readerContainer = document.querySelector(".reader-container");
    document.getElementById("width-narrow-btn").addEventListener("click", () => {
        readerContainer.style.maxWidth = "800px";
        document.getElementById("width-narrow-btn").classList.add("active");
        document.getElementById("width-wide-btn").classList.remove("active");
    });
    
    document.getElementById("width-wide-btn").addEventListener("click", () => {
        readerContainer.style.maxWidth = "100%";
        document.getElementById("width-wide-btn").classList.add("active");
        document.getElementById("width-narrow-btn").classList.remove("active");
    });
}

