// Lord Dashboard Logic
function renderDashboard() {
    updateDashboardUI();

    const problemListContainer = document.getElementById("dashboard-problems-list");
    problemListContainer.innerHTML = CITY_PROBLEMS.map(p => {
        const isSolved = solvedProblems.includes(p.id);
        return `
            <div class="issue-item" id="issue-${p.id}" style="${isSolved ? 'opacity: 0.6; border-left: 3px solid var(--color-secondary);' : ''}">
                <div>
                    <span class="issue-cat">[ข้อที่ ${p.num} | ${p.cat}]</span>
                    <div class="issue-name">${p.title}</div>
                    <div style="font-size: 0.8rem; color: var(--color-gold); margin-top: 4px;">ผลสัมฤทธิ์: ${p.reward}</div>
                </div>
                <div>
                    ${isSolved ? 
                        '<span style="color: var(--color-secondary); font-weight: bold; font-size: 0.9rem;">แก้ไขแล้ว</span>' : 
                        `<button class="issue-action-btn" onclick="triggerSolveProblem(${p.id})">แก้ไขปัญหา (ใช้แร่ ${p.cost})</button>`
                    }
                </div>
            </div>
        `;
    }).join('');
}

function updateDashboardUI() {
    const ownerName = document.querySelector(".dash-owner-info h3");
    const ownerDesc = document.querySelector(".dash-owner-info span");
    if (ownerName) {
        if (lordResources.reincarnationLoop > 1) {
            ownerName.innerHTML = `เย่ซิงเฉิน (Ye Xingchen) <span style="font-size: 0.8rem; color: #b388ff; border: 1px solid #b388ff; padding: 2px 6px; border-radius: 4px; margin-left: 8px; font-weight: normal; background: rgba(106, 27, 154, 0.25);">ชาติภพที่ ${lordResources.reincarnationLoop}</span>`;
            if (ownerDesc) {
                ownerDesc.innerText = `เจ้าสำนักกระบี่ดาวเหนือผู้เกิดใหม่ (หลินเทียน) | จิตวิญญาณ: Core Essence Saint`;
            }
        } else {
            ownerName.innerHTML = `หลินเทียน (Lin Tian)`;
            if (ownerDesc) {
                ownerDesc.innerText = `เจ้าสำนักกระบี่ดาวเหนือ & เจ้าเมืองหมอกสวรรค์ | จิตวิญญาณ: Core Essence Saint`;
            }
        }
    }

    document.getElementById("stat-iron").innerText = lordResources.iron;
    document.getElementById("stat-food").innerText = `${lordResources.food} วัน`;
    document.getElementById("stat-security").innerText = `${lordResources.security}%`;
    document.getElementById("stat-population").innerText = `${lordResources.population} คน`;
    
    // Cosmic Reincarnation Stats Update
    const statLoop = document.getElementById("stat-loop");
    const statAge = document.getElementById("stat-age");
    const statRank = document.getElementById("stat-rank");
    const statAura = document.getElementById("stat-aura");
    if (statLoop) statLoop.innerText = lordResources.reincarnationLoop;
    if (statAge) statAge.innerText = `${lordResources.currentAge} / ${lordResources.loopLifespan} ปี`;
    if (statRank) statRank.innerText = `อันดับที่ ${lordResources.sectRank}`;
    if (statAura) statAura.innerText = lordResources.soulAura;
    
    const secBox = document.getElementById("stat-box-security");
    if (lordResources.security < 50) {
        secBox.className = "stat-box danger";
    } else {
        secBox.className = "stat-box success";
    }
}

function setupDashboardActions() {
    document.getElementById("btn-mine-iron").addEventListener("click", () => {
        if (solvedProblems.includes(329)) {
            lordResources.iron += 150;
            showModal("ขุดแร่เหล็กสำเร็จ", "ขอบพระคุณท่านเจ้าสำนัก! เนื่องจากท่านได้ปราบปรามยอดฝีมือสำนักกระบี่เงาโลหิตและเปิดทางเข้าเหมืองคืนได้สำเร็จ คนงานสำนักค้อนศิลาทลายสามารถขุดเหล็กได้อย่างรวดเร็ว ได้รับแร่เหล็กเพิ่มเติม +150 หน่วย!");
        } else {
            lordResources.iron += 30;
            showModal("ขุดแร่เหล็กจำกัด", "คนงานขุดแร่ได้เพียงชายขอบหุบเขา เนื่องจากทางเข้าหลักยังโดน <strong>กลุ่มศิษย์ทรยศสำนักกระบี่เงาโลหิต</strong> และค่ายกลศิลาขวางทางอยู่ ได้รับแร่เหล็กดิบ +30 หน่วย (โปรดชำระปัญหาเหมืองเพื่อเริ่มขุดแร่เต็มกำลัง!)");
        }
        updateDashboardUI();
        renderDashboard();
    });

    document.getElementById("btn-buy-food").addEventListener("click", () => {
        if (lordResources.iron >= 100) {
            lordResources.iron -= 100;
            lordResources.food += 5;
            showModal("จัดซื้อเสบียงอาหาร", "แลกเปลี่ยนแร่เหล็กดิบ 100 หน่วย กับสมาคมพ่อค้าเพื่อนำข้าวสารกลับมาแจกจ่ายชาวเมืองและศิษย์พรรคต่างๆ เสบียงอาหารเพิ่มขึ้น +5 วัน");
            updateDashboardUI();
            renderDashboard();
        } else {
            showModal("แร่เหล็กไม่เพียงพอ", "ท่านต้องการแร่เหล็กดิบอย่างน้อย 100 หน่วย ในการแลกซื้ออาหารกับขบวนสินค้าคาราวาน");
        }
    });

    // Reincarnation Action Trigger
    document.getElementById("btn-reincarnate").addEventListener("click", () => {
        lordResources.reincarnationLoop++;
        lordResources.soulAura += 40;
        
        // Lifespan increases as he accumulates soul power
        lordResources.loopLifespan += 20; 
        
        // Sect Rank climbs as he makes more progress
        if (lordResources.sectRank > 1) {
            lordResources.sectRank--;
        }
        
        // Reset local loop resources, simulating rebirth
        lordResources.currentAge = 16;
        lordResources.iron = 820 + (lordResources.reincarnationLoop * 50);
        lordResources.food = 15;
        lordResources.security = 45;
        solvedProblems = []; // Reset solved problems for this rebirth loop
        
        showModal(
            `วัฏจักรจุติสวรรค์ - เกิดใหม่รอบที่ ${lordResources.reincarnationLoop}`, 
            `
            <p style="font-style: italic; color: #b388ff; margin-bottom: 15px;">
                "สัจธรรมแห่งสังสารวัฏหมุนวน ดับสลายรื้อกายหยาบเพื่อวิญญาณสุกสกาวดั่งดาวเหนือ..."
            </p>
            <p>วิญญาณของท่านดับสูญลงจากการเสียชีวิตในชาติภพก่อน พลังจิตวิญญาณดวงดาวใน <strong>กระบี่ดาวเหนือ</strong> เหนี่ยวนำดวงดาราย้อนวิญญาณกลับสู่ครรภ์มารดา <strong>ท่านได้ถือกำเนิดใหม่เป็นเด็กทารกแบเบาะ (Infant)</strong> ขยับมือเท้าอ้อแอ้โดยมีความทรงจำจากชาติปางก่อนอยู่ครบถ้วน!</p>
            <p style="margin-top: 10px;">• <strong>อายุ 0-6 ปี</strong>: นอนเติบโตในเปลไม้ไผ่ รอคอยให้เส้นชีพจรลมปราณทารกสมานตัวมั่นคง</p>
            <p>• <strong>อายุ 7 ปี</strong>: เริ่มเดินพลังปราณดาวเหนือ ขัดเกลากระดูก แอบฝึกปรือวิชาในเงามืดเป็นเวลา 9 ปีเต็ม</p>
            <p>• <strong>อายุ 16 ปี</strong>: สำเร็จพลังดาราบุกกลับสำนักกระบี่ดาวเหนือ ปราบรองเจ้าสำนักคอร์รัปชัน ทวงคืนตำแหน่งเจ้าสำนักได้สำเร็จ!</p>
            <div style="margin-top: 15px; border-top: 1px dashed rgba(255,255,255,0.1); padding-top: 10px; color: var(--color-gold);">
                <strong>ผลสัมฤทธิ์ข้ามลูป:</strong><br>
                - ได้รับพลังวิญญาณสะสม (Soul Aura) <strong>+40 แต้ม</strong> (รวมเป็น ${lordResources.soulAura} แต้ม)<br>
                - ขยายขีดจำกัดอายุขัยในชาติภพใหม่เป็น <strong>${lordResources.loopLifespan} ปี</strong><br>
                - อันดับสำนักขยับขึ้นสูงเป็น <strong>อันดับที่ ${lordResources.sectRank}</strong> ของยุทธภพ!
            </div>
            `
        );
        updateDashboardUI();
        renderDashboard();
    });
}

// Action triggered by clicking Solve Problem
window.triggerSolveProblem = function(problemId) {
    const prob = CITY_PROBLEMS.find(p => p.id === problemId);
    if (!prob) return;
    
    if (lordResources.iron < prob.cost) {
        showModal("แร่เหล็กไม่เพียงพอ", `ท่านไม่มีแร่เหล็กเพียงพอสำหรับการแก้ปัญหานี้ (ต้องการ ${prob.cost} หน่วย แต่มีเพียง ${lordResources.iron} หน่วย)`);
        return;
    }
    
    lordResources.iron -= prob.cost;
    solvedProblems.push(problemId);
    
    let storySolveText = "";
    if (problemId === 1) {
        lordResources.security += 5;
        storySolveText = "ท่านหลินเทียน เจ้าสำนักกระบี่ดาวเหนือ บัญชาการศิษย์ร่วมมือกับชาวเมืองเก็บกวาดเศษซากความเสียหายจากสงครามและจัดพิธีศพอย่างสมเกียรติ ยกระดับสุขอนามัยรอบฐานที่มั่น!";
    } else if (problemId === 14) {
        lordResources.security += 5;
        lordResources.food += 2;
        storySolveText = "ด้วยการนำทางของพลังจิตสัมผัส หลินเทียน ร่วมมือกับศิษย์สำนักหญ้าโอสถ เข้าตรวจสอบบ่อน้ำเก่า ชำระล้างซากเน่าเสียและโรยผงยาฆ่าเชื้อจนน้ำกลับมาดื่มกินได้ปลอดภัย!";
    } else if (problemId === 31) {
        lordResources.food += 10;
        storySolveText = "จัดตั้งคลังเก็บพืชผลข้าวสารใหม่ที่มีระบบระบายควันและความชื้น โดยประสานกับพรรคเมฆาคล้อยคอยเฝ้าระวังไม่ให้เกิดรอยรั่ว เสบียงยืดอายุเพิ่ม +10 วัน!";
    } else if (problemId === 48) {
        lordResources.security += 5;
        storySolveText = "จัดสรรฟืนจากภูเขาโดยให้ศิษย์สำนักหมาป่าศิลาช่วยดูแลอย่างทั่วถึง ทหารและราษฎรมีไออุ่นในเตาเพลิง ไม่รุกล้ำบ้านผู้อื่น";
    } else if (problemId === 107) {
        lordResources.security += 12;
        storySolveText = "ด้วยประสาทจิตสแกน หลินเทียน ตรวจพบโพรงขุดลอบใต้กำแพงของกลุ่มนักฆ่ากระบี่เงาโลหิต จึงสั่งให้ศิษย์ค่ายเสือทะยานนำปูนเหนียวโบกอุดทางจนหมดสิ้น ป้องกันลอบโจมตียามวิกาล!";
    } else if (problemId === 134) {
        lordResources.security += 8;
        storySolveText = "สั่งระดมพลช่างก่อสร้างสำนักค่ายกลสายลม โบกปูนเหนียวหนาทับรอยแตกของกำแพงเมืองด้านทิศตะวันตกที่เกิดจากแดดเผาจนแข็งแกร่งดั่งหินผา";
    } else if (problemId === 177) {
        lordResources.security += 5;
        storySolveText = "จัดระบบการทำงานใหม่ ย้ายโรงเตาหลอมของสำนักเตาอัคคีสวรรค์ที่แผ่ไอร้อนและเสียงดังไปตั้งอยู่นอกเขตย่านชุมชนทางทิศใต้ ช่วยให้บรรยากาศในเมืองน่าอยู่ขึ้น";
    } else if (problemId === 215) {
        lordResources.food += 4;
        lordResources.security += 4;
        storySolveText = "ซ่อมคันกั้นลำน้ำคลองส่งน้ำ โดยให้ศิษย์สำนักวารีลื่นไหลประยุกต์ใช้แผ่นประตูปิดเปิดเหล็ก ปรับน้ำสะอาดเข้านาข้าวได้ถูกต้องตามฤดูกาล";
    } else if (problemId === 329) {
        lordResources.iron += 500;
        storySolveText = "หลินเทียน นำหน่วยโล่ค่ายเสือทะยานและศิษย์กระบี่ดาวเหนือ บุกปะทะกับยอดฝีมือของ <strong>สำนักกระบี่เงาโลหิต</strong> ค่ายศิลากลไกถูกหลินเทียนใช้พลังจิตสัมผัสสแกนหาแกนจุดทำลายจนกลไกแตกกระเจิง ยึดทางเข้าเหมืองและสายแร่เหล็กดิบคืนได้สำเร็จ รับแร่สะสมดิบ +500 หน่วย!";
    } else if (problemId === 355) {
        lordResources.iron += 100;
        storySolveText = "ประสานงานช่างหลอมเตาอัคคีสวรรค์ซ่อมฐานเตาพลังด้วยค่ายกลดาวจระเข้ ทำให้การคุมเพลิงปรุงยาและสร้างเกราะโลหะอักขระแม่นยำสูง";
    } else if (problemId === 381) {
        lordResources.security += 6;
        storySolveText = "กางแนวรบกับดักตะแกรงสายลมสิบแปดทิศรอบป้อมยาม สุนัขสงครามและหมาป่าอสุรศิลารอบป่าสงบเงียบลง นำกระดูกสัตว์อสูรมาวิเคราะห์เป็นแกนสลักอักขระ";
    } else {
        lordResources.security += 5;
        storySolveText = "ขจัดปัญหาประปาขยะสะสมในกำแพงเมือง ทำให้ผู้คนพึงพอใจและอาคารสิ่งปลูกสร้างมั่นคงขึ้น!";
    }

    showModal("แก้ไขปัญหาเมืองสำเร็จ", `
        <p>${storySolveText}</p>
        <p style="margin-top:15px; color: var(--color-secondary);"><strong>รางวัลที่ได้รับ:</strong> ${prob.reward}</p>
    `);
    
    updateDashboardUI();
    renderDashboard();
};

// Modal helpers
function showModal(title, contentHTML) {
    const modal = document.getElementById("system-modal");
    document.getElementById("modal-title-text").innerText = title;
    document.getElementById("modal-body-content").innerHTML = contentHTML;
    modal.classList.add("active");
}

window.closeSystemModal = function() {
    document.getElementById("system-modal").classList.remove("active");
};

window.addEventListener("click", (e) => {
    const modal = document.getElementById("system-modal");
    if (e.target === modal) {
        closeSystemModal();
    }
});